    // 基准：2000-01-07 = 角木蛟（索引 0）
    private val BASE_DATE = LocalDate.of(2000, 1, 7)

    val all: List<Mansion> get() = MANSTIONS

    /** 按日期取值日星宿（与出生本命同算法） */
    fun byDate(date: LocalDate): Mansion {
        val days = ChronoUnit.DAYS.between(BASE_DATE, date)
        val idx = ((days % 28) + 28) % 28
        return MANSTIONS[idx.toInt()]
    }

    /** 按名称查星宿 */
    fun byName(name: String): Mansion? = MANSTIONS.firstOrNull { it.name == name }

    /** 按四象分组 */
    fun byConstellation(): Map<String, List<Mansion>> = MANSTIONS.groupBy { it.constellation }
}
